-- Replaces the Prisma-generated schema from 20261020025112_init with one built
-- for supabase-js: ids and timestamps are generated by the database, dates use
-- timestamptz, and the tag join table has readable column names. The old
-- tables held no data when this ran, so they are dropped and recreated.
drop table public."_TagToTransaction", public."Transaction", public."Tag", public."Category", public."Account", public."User";
drop type public."AccountType", public."CategoryType", public."TransactionType";

-- NiHi schema. The app talks to the database only from the server, through
-- supabase-js with the secret key (service_role), which bypasses row level
-- security. RLS is on with no policies, so the public API roles (anon,
-- authenticated) cannot read or write anything.

create type public."AccountType" as enum ('CASH', 'BANK', 'SAVINGS', 'CREDIT_CARD', 'INVESTMENT', 'OTHER');
create type public."CategoryType" as enum ('INCOME', 'EXPENSE');
create type public."TransactionType" as enum ('INCOME', 'EXPENSE', 'TRANSFER');

create table public."User" (
  "id" text primary key default gen_random_uuid()::text,
  "email" text not null unique,
  "name" text not null,
  "passwordHash" text not null,
  "defaultCurrency" text not null default 'LKR',
  "createdAt" timestamptz not null default now(),
  "updatedAt" timestamptz not null default now()
);

-- Amounts are stored in minor units (cents).
create table public."Account" (
  "id" text primary key default gen_random_uuid()::text,
  "userId" text not null references public."User" ("id") on delete cascade,
  "name" text not null,
  "type" public."AccountType" not null default 'CASH',
  "currency" text not null,
  "initialBalance" integer not null default 0,
  "color" text not null,
  "note" text not null default '',
  "archived" boolean not null default false,
  "createdAt" timestamptz not null default now()
);
create index "Account_userId_idx" on public."Account" ("userId");

create table public."Category" (
  "id" text primary key default gen_random_uuid()::text,
  "userId" text not null references public."User" ("id") on delete cascade,
  "name" text not null,
  "type" public."CategoryType" not null,
  "color" text not null,
  -- Key into CATEGORY_ICONS in src/lib/category-icons.tsx.
  "icon" text not null default 'other',
  "createdAt" timestamptz not null default now(),
  unique ("userId", "type", "name")
);

create table public."Tag" (
  "id" text primary key default gen_random_uuid()::text,
  "userId" text not null references public."User" ("id") on delete cascade,
  "name" text not null,
  "color" text not null,
  "createdAt" timestamptz not null default now(),
  unique ("userId", "name")
);

-- `date` is stored at 12:00 UTC of the calendar day the user picked.
-- For transfers, `amount` leaves `accountId` and `toAmount` arrives in `toAccountId`.
create table public."Transaction" (
  "id" text primary key default gen_random_uuid()::text,
  "userId" text not null references public."User" ("id") on delete cascade,
  "type" public."TransactionType" not null,
  "amount" integer not null,
  "accountId" text not null references public."Account" ("id") on delete restrict,
  "toAccountId" text references public."Account" ("id") on delete restrict,
  "toAmount" integer,
  "categoryId" text references public."Category" ("id") on delete set null,
  "date" timestamptz not null,
  "note" text not null default '',
  "createdAt" timestamptz not null default now()
);
create index "Transaction_userId_date_idx" on public."Transaction" ("userId", "date");
create index "Transaction_accountId_idx" on public."Transaction" ("accountId");
create index "Transaction_toAccountId_idx" on public."Transaction" ("toAccountId");
create index "Transaction_categoryId_idx" on public."Transaction" ("categoryId");

create table public."TransactionTag" (
  "transactionId" text not null references public."Transaction" ("id") on delete cascade,
  "tagId" text not null references public."Tag" ("id") on delete cascade,
  primary key ("transactionId", "tagId")
);
create index "TransactionTag_tagId_idx" on public."TransactionTag" ("tagId");

create function public.set_updated_at() returns trigger
language plpgsql set search_path = '' as $$
begin
  new."updatedAt" = now();
  return new;
end;
$$;

create trigger "User_set_updated_at" before update on public."User"
for each row execute function public.set_updated_at();

alter table public."User" enable row level security;
alter table public."Account" enable row level security;
alter table public."Category" enable row level security;
alter table public."Tag" enable row level security;
alter table public."Transaction" enable row level security;
alter table public."TransactionTag" enable row level security;

-- Aggregates the REST API cannot express. Each one is scoped to one user.

-- Net change per account from all its activity, to add to initialBalance.
create function public.account_balance_deltas(p_user_id text)
returns table ("accountId" text, "delta" bigint)
language sql stable set search_path = '' as $$
  select id, sum(change)::bigint
  from (
    select t."accountId" as id, case when t."type" = 'INCOME' then t."amount" else -t."amount" end as change
    from public."Transaction" t
    where t."userId" = p_user_id
    union all
    select t."toAccountId", coalesce(t."toAmount", 0)
    from public."Transaction" t
    where t."userId" = p_user_id and t."type" = 'TRANSFER' and t."toAccountId" is not null
  ) moves
  group by id;
$$;

-- Income and expense per currency in [p_start, p_end). Transfers are not counted.
create function public.totals_by_currency(p_user_id text, p_start timestamptz, p_end timestamptz)
returns table ("currency" text, "income" bigint, "expense" bigint)
language sql stable set search_path = '' as $$
  select a."currency",
    coalesce(sum(t."amount") filter (where t."type" = 'INCOME'), 0)::bigint,
    coalesce(sum(t."amount") filter (where t."type" = 'EXPENSE'), 0)::bigint
  from public."Transaction" t
  join public."Account" a on a."id" = t."accountId"
  where t."userId" = p_user_id
    and t."type" in ('INCOME', 'EXPENSE')
    and t."date" >= p_start and t."date" < p_end
  group by a."currency";
$$;

-- Totals per category for one type and currency in [p_start, p_end).
-- Uncategorized transactions come back with a null category.
create function public.category_breakdown(
  p_user_id text, p_type public."TransactionType", p_currency text, p_start timestamptz, p_end timestamptz
)
returns table ("id" text, "name" text, "color" text, "icon" text, "total" bigint, "count" bigint)
language sql stable set search_path = '' as $$
  select c."id", c."name", c."color", c."icon", sum(t."amount")::bigint, count(*)
  from public."Transaction" t
  join public."Account" a on a."id" = t."accountId"
  left join public."Category" c on c."id" = t."categoryId"
  where t."userId" = p_user_id
    and t."type" = p_type
    and a."currency" = p_currency
    and t."date" >= p_start and t."date" < p_end
  group by c."id";
$$;

-- Income and expense per "YYYY-MM" month in [p_start, p_end), in one currency.
create function public.monthly_totals(p_user_id text, p_currency text, p_start timestamptz, p_end timestamptz)
returns table ("month" text, "income" bigint, "expense" bigint)
language sql stable set search_path = '' as $$
  select to_char(t."date" at time zone 'UTC', 'YYYY-MM'),
    coalesce(sum(t."amount") filter (where t."type" = 'INCOME'), 0)::bigint,
    coalesce(sum(t."amount") filter (where t."type" = 'EXPENSE'), 0)::bigint
  from public."Transaction" t
  join public."Account" a on a."id" = t."accountId"
  where t."userId" = p_user_id
    and t."type" in ('INCOME', 'EXPENSE')
    and a."currency" = p_currency
    and t."date" >= p_start and t."date" < p_end
  group by 1;
$$;

-- Creates (p_id null) or updates a transaction and replaces its tags in one
-- step. The caller checks that every referenced row belongs to p_user_id.
-- Returns the transaction id, or null when p_id does not belong to the user.
create function public.save_transaction(
  p_user_id text,
  p_id text,
  p_type public."TransactionType",
  p_amount integer,
  p_account_id text,
  p_to_account_id text,
  p_to_amount integer,
  p_category_id text,
  p_date timestamptz,
  p_note text,
  p_tag_ids text[]
)
returns text
language plpgsql set search_path = '' as $$
declare
  v_id text;
begin
  if p_id is null then
    insert into public."Transaction"
      ("userId", "type", "amount", "accountId", "toAccountId", "toAmount", "categoryId", "date", "note")
    values
      (p_user_id, p_type, p_amount, p_account_id, p_to_account_id, p_to_amount, p_category_id, p_date, p_note)
    returning "id" into v_id;
  else
    update public."Transaction"
    set "type" = p_type, "amount" = p_amount, "accountId" = p_account_id, "toAccountId" = p_to_account_id,
        "toAmount" = p_to_amount, "categoryId" = p_category_id, "date" = p_date, "note" = p_note
    where "id" = p_id and "userId" = p_user_id
    returning "id" into v_id;
    if v_id is null then
      return null;
    end if;
    delete from public."TransactionTag" where "transactionId" = v_id;
  end if;

  insert into public."TransactionTag" ("transactionId", "tagId")
  select v_id, tag_id from unnest(coalesce(p_tag_ids, '{}')) as tag_id;
  return v_id;
end;
$$;

-- Only the server (service_role) may call these.
revoke execute on function public.account_balance_deltas(text) from public, anon, authenticated;
revoke execute on function public.totals_by_currency(text, timestamptz, timestamptz) from public, anon, authenticated;
revoke execute on function public.category_breakdown(text, public."TransactionType", text, timestamptz, timestamptz) from public, anon, authenticated;
revoke execute on function public.monthly_totals(text, text, timestamptz, timestamptz) from public, anon, authenticated;
revoke execute on function public.save_transaction(text, text, public."TransactionType", integer, text, text, integer, text, timestamptz, text, text[]) from public, anon, authenticated;
grant execute on function public.account_balance_deltas(text) to service_role;
grant execute on function public.totals_by_currency(text, timestamptz, timestamptz) to service_role;
grant execute on function public.category_breakdown(text, public."TransactionType", text, timestamptz, timestamptz) to service_role;
grant execute on function public.monthly_totals(text, text, timestamptz, timestamptz) to service_role;
grant execute on function public.save_transaction(text, text, public."TransactionType", integer, text, text, integer, text, timestamptz, text, text[]) to service_role;
